/**
 * Shop by Industry pages - mobile header, card behaviour, category chips, the filter sidebar/drawer and the
 * "More ..." section (markup generated by scripts/build-industries.js, same classes as the shop).
 *
 * Curated cards are in the HTML. Filter values for every style on the page, and the cards for the
 * "More ..." section, come from brandedukv15-child/assets/data/industries/<sector>.json.
 */
(function () {
    'use strict';

    var MOBILE_BREAKPOINT = 700;
    var VAT_RATE = 0.20;
    var FILTER_VISIBLE_LIMIT = 8;
    var ICONS = {
        crown: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M3.5 17.5h17"/><path d="M4 17.5 6.2 9.2 10 13.2 12 6.2 14 13.2 17.8 9.2 20 17.5"/><circle cx="6.2" cy="7.4" r="1.15" fill="currentColor" stroke="none"/><circle cx="12" cy="4.6" r="1.15" fill="currentColor" stroke="none"/><circle cx="17.8" cy="7.4" r="1.15" fill="currentColor" stroke="none"/></svg>',
        needle: '<svg viewBox="0 0 40 28" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M1 8c2.2-3 4-2 5.2.6"/><path d="M2 7.5h12"/><path d="M3 7.5v13M13 7.5v13"/><path d="M2 20.5h12"/><path d="M3.4 11h9.2M3.4 14.2h9.2M3.4 17.2h9.2"/><path d="M13.5 9.5c3-1.4 4.6.4 5.2 2.4"/><path d="M22 5.2 35.2 24"/><circle cx="23.6" cy="7.6" r="1.15" fill="currentColor" stroke="none"/><circle cx="27.2" cy="13" r="0.85" fill="currentColor" stroke="none"/><circle cx="30.4" cy="17.6" r="0.85" fill="currentColor" stroke="none"/><circle cx="33.6" cy="22.2" r="0.85" fill="currentColor" stroke="none"/></svg>',
        shirt: '<svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M8.2 4.2 4 7.2l2.1 2.6 2-1.1V20h7.8V8.7l2 1.1L20 7.2l-4.2-3-1.6 2.2H9.8L8.2 4.2z"/></svg>'
    };

    function isMobile() {
        return window.innerWidth < MOBILE_BREAKPOINT || /Mobi|Android|iPhone|iPod/i.test(navigator.userAgent || '');
    }

    function escapeHtml(value) {
        return String(value == null ? '' : value)
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;');
    }

    function styles(count) {
        return count + (count === 1 ? ' style' : ' styles');
    }

    /* Same destinations product-detail.html redirects /product/<code> to, without the extra hop. */
    function productUrl(code) {
        var safeCode = encodeURIComponent(code);
        return isMobile()
            ? '/mobile/customize-mobile.html?code=' + safeCode
            : '/shop-pc.html?product=' + safeCode;
    }

    function vatIsOn() {
        var api = window.brandedukv15 && window.brandedukv15.vat;
        if (api && typeof api.isOn === 'function') return !!api.isOn();
        try {
            return localStorage.getItem('brandeduk-vat-mode') === 'on';
        } catch (error) {
            return false;
        }
    }

    function vatFactor() {
        return vatIsOn() ? 1 + VAT_RATE : 1;
    }

    function renderPrices(scope) {
        var on = vatIsOn();
        var suffix = on ? 'inc VAT' : 'ex VAT';
        (scope || document).querySelectorAll('.product-price[data-price]').forEach(function (price) {
            var base = parseFloat(price.getAttribute('data-price')) || 0;
            var value = price.querySelector('.price-value');
            var label = price.querySelector('.price-suffix');
            if (value) value.textContent = '\u00A3' + (on ? base * (1 + VAT_RATE) : base).toFixed(2);
            if (label) label.textContent = suffix;
        });
        if (!scope) {
            document.querySelectorAll('[data-ind-vat-label]').forEach(function (label) {
                label.textContent = suffix;
            });
        }
    }

    /* ------------------------------------------------------------------ cards */

    function paintDots(card) {
        if (card.dataset.dotsPainted) return;
        card.dataset.dotsPainted = '1';
        card.querySelectorAll('.color-dot[data-main]').forEach(function (dot) {
            dot.style.backgroundImage = 'url("' + dot.getAttribute('data-main').replace(/"/g, '%22') + '")';
        });
    }

    var dotObserver = 'IntersectionObserver' in window ? new IntersectionObserver(function (entries) {
        entries.forEach(function (entry) {
            if (!entry.isIntersecting) return;
            paintDots(entry.target);
            dotObserver.unobserve(entry.target);
        });
    }, { rootMargin: '400px 0px' }) : null;

    function watchDots(card) {
        if (dotObserver) dotObserver.observe(card);
        else paintDots(card);
    }

    function initCard(card) {
        var image = card.querySelector('.product-image');
        var colors = card.querySelector('.product-colors');
        var progress = card.querySelector('.color-progress-bar');
        var code = card.getAttribute('data-code');
        var modelImage = image ? image.getAttribute('src') : '';

        if (image) {
            image.addEventListener('error', function onError() {
                var fallback = card.querySelector('.color-dot[data-main]');
                image.removeEventListener('error', onError);
                if (fallback && fallback.getAttribute('data-main') !== image.getAttribute('src')) {
                    image.src = fallback.getAttribute('data-main');
                } else {
                    console.warn('[industries] No image available for', code);
                }
            });
        }

        card.querySelectorAll('.color-dot').forEach(function (dot) {
            dot.addEventListener('click', function (event) {
                event.stopPropagation();
                if (image && dot.getAttribute('data-main')) image.src = dot.getAttribute('data-main');
                card.querySelectorAll('.color-dot').forEach(function (other) { other.classList.remove('active'); });
                dot.classList.add('active');
            });
        });

        var prev = card.querySelector('.color-prev');
        var next = card.querySelector('.color-next');
        if (colors && prev && next) {
            prev.addEventListener('click', function (event) {
                event.stopPropagation();
                colors.scrollLeft -= 120;
            });
            next.addEventListener('click', function (event) {
                event.stopPropagation();
                colors.scrollLeft += 120;
            });
            colors.addEventListener('scroll', function () {
                var max = colors.scrollWidth - colors.clientWidth;
                var pct = max > 0 ? ((colors.scrollLeft + colors.clientWidth) / colors.scrollWidth) * 100 : 100;
                if (progress) progress.style.width = pct + '%';
            }, { passive: true });
        }

        card.addEventListener('click', function (event) {
            if (event.defaultPrevented || event.button !== 0 || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return;
            if (event.target.closest('button')) return;
            event.preventDefault();
            try {
                /* customize.js falls back to selectedProductData (e.g. its model image) without
                   checking the code, so a previous product's data must never be left behind. */
                var nameEl = card.querySelector('.product-name');
                var brandEl = card.querySelector('.brand-logo, .brand-name');
                var priceEl = card.querySelector('.product-price[data-price]');
                sessionStorage.setItem('selectedProduct', code);
                sessionStorage.setItem('selectedProductData', JSON.stringify({
                    code: code,
                    name: nameEl ? nameEl.textContent.trim() : code,
                    brand: brandEl ? (brandEl.getAttribute('alt') || brandEl.textContent.trim()) : '',
                    price: priceEl ? parseFloat(priceEl.getAttribute('data-price')) || 0 : 0,
                    image: modelImage
                }));
                sessionStorage.setItem('customizeFreshItem', '1');
                var active = card.querySelector('.color-dot.active');
                if (active && active.getAttribute('data-color') !== 'model') {
                    sessionStorage.setItem('selectedColorName', active.getAttribute('data-color'));
                    sessionStorage.setItem('selectedColorUrl', active.getAttribute('data-main'));
                } else {
                    sessionStorage.removeItem('selectedColorName');
                    sessionStorage.removeItem('selectedColorUrl');
                }
            } catch (error) {
                // Storage can be unavailable in private browsing; navigation still works.
            }
            window.location.href = productUrl(code);
        });
    }

    /* Same markup as productCard() in scripts/build-industries.js. */
    function cardHtml(record, data) {
        var image = function (url) {
            return url && url.charAt(0) === '~' ? data.imageBase + url.slice(1) : url;
        };
        var href = '/product/' + encodeURIComponent(record.c);
        var methods = [];
        if (record.m & 1) methods.push('<span class="method-item best-seller">' + ICONS.crown + '<span>Best Seller</span></span>');
        if (record.m & 2) methods.push('<span class="method-item recommended"><span>Recommended</span></span>');
        if (record.m & 4) methods.push('<span class="method-item embroidery">' + ICONS.needle + '<span>EMB</span></span>');
        if ((record.m & 8) && !/beanie/i.test(record.n)) methods.push('<span class="method-item print">' + ICONS.shirt + '<span>Print</span></span>');

        var logo = record.b && data.logos[record.b];
        var brandHtml = !record.b ? '' : logo
            ? '<img src="' + escapeHtml(logo) + '" alt="' + escapeHtml(record.b) + '" class="brand-logo" title="' + escapeHtml(record.b) + '" loading="lazy" decoding="async">'
            : '<span class="brand-name">' + escapeHtml(record.b) + '</span>';

        var colors = record.k || [];
        var dots = colors.map(function (color, index) {
            return '<button type="button" class="color-dot' + (index === 0 ? ' active' : '') + '" data-color="' + escapeHtml(color[0]) + '" data-main="' + escapeHtml(image(color[1])) + '" title="' + escapeHtml(color[0]) + '" aria-label="' + escapeHtml(color[0]) + '"></button>';
        }).join('');
        var controls = colors.length > 6
            ? '<div class="color-slider-controls"><button type="button" class="color-arrow color-prev" aria-label="Previous colours">&lsaquo;</button><div class="color-progress"><div class="color-progress-bar" style="width: ' + Math.min(100, (7 / colors.length) * 100).toFixed(0) + '%;"></div></div><button type="button" class="color-arrow color-next" aria-label="Next colours">&rsaquo;</button></div>'
            : '';

        return '<article class="product-card" data-code="' + escapeHtml(record.c) + '" data-href="' + href + '">'
            + '<a class="product-media" href="' + href + '" tabindex="-1" aria-hidden="true"><img src="' + escapeHtml(image(record.i)) + '" alt="' + escapeHtml(record.n) + '" class="product-image" width="400" height="400" loading="lazy" decoding="async"></a>'
            + '<div class="product-info">'
            + '<div class="product-method-row">' + methods.join('<span class="method-sep" aria-hidden="true"></span>') + '</div>'
            + '<div class="product-code-row"><span class="product-code">' + escapeHtml(record.c) + '</span>' + brandHtml + '</div>'
            + '<h3 class="product-name"><a href="' + href + '">' + escapeHtml(record.n) + '</a></h3>'
            + '<div class="product-price" data-price="' + record.p.toFixed(2) + '"><span class="price-label">From</span><span class="price-value">\u00A3' + record.p.toFixed(2) + '</span><span class="price-suffix">ex VAT</span></div>'
            + '<div class="product-colors-wrapper"><div class="product-colors">' + dots + '</div>' + controls + '</div>'
            + '</div></article>';
    }

    /* ------------------------------------------------------------------ category chips */

    function initJump() {
        var nav = document.querySelector('[data-ind-jump]');
        if (!nav) return function () {};
        var row = nav.querySelector('[data-ind-jump-row]');
        var prev = nav.querySelector('[data-ind-jump-prev]');
        var next = nav.querySelector('[data-ind-jump-next]');

        function update() {
            var max = row.scrollWidth - row.clientWidth;
            var hasPrev = row.scrollLeft > 2;
            var hasNext = row.scrollLeft < max - 2;
            nav.classList.toggle('has-prev', hasPrev);
            nav.classList.toggle('has-next', hasNext);
            prev.hidden = !hasPrev;
            next.hidden = !hasNext;
        }

        prev.addEventListener('click', function () {
            row.scrollBy({ left: -Math.max(160, row.clientWidth * 0.7), behavior: 'smooth' });
        });
        next.addEventListener('click', function () {
            row.scrollBy({ left: Math.max(160, row.clientWidth * 0.7), behavior: 'smooth' });
        });
        row.addEventListener('scroll', update, { passive: true });
        window.addEventListener('resize', update);
        if ('ResizeObserver' in window) new ResizeObserver(update).observe(row);
        /* Keep a keyboard-focused chip clear of the arrow buttons and edge fades. */
        row.addEventListener('focusin', function (event) {
            var chip = event.target;
            var pad = window.innerWidth < MOBILE_BREAKPOINT ? 24 : 48;
            var chipBox = chip.getBoundingClientRect();
            var rowBox = row.getBoundingClientRect();
            var delta = 0;
            if (chipBox.left < rowBox.left + pad) delta = chipBox.left - rowBox.left - pad;
            else if (chipBox.right > rowBox.right - pad) delta = chipBox.right - rowBox.right + pad;
            if (delta) row.scrollTo({ left: row.scrollLeft + delta, behavior: 'instant' });
        });
        row.addEventListener('click', function (event) {
            var link = event.target.closest('a[data-ind-chip]');
            var target = link && document.getElementById(link.getAttribute('data-ind-chip'));
            if (!target || event.metaKey || event.ctrlKey || event.shiftKey) return;
            event.preventDefault();
            target.scrollIntoView({ behavior: 'smooth', block: 'start' });
            if (history.replaceState) history.replaceState(null, '', '#' + target.id);
        });
        update();
        return update;
    }

    /* ------------------------------------------------------------------ filters */

    function initFilters(updateJump) {
        var body = document.querySelector('[data-ind-filters]');
        var dataUrl = document.body.getAttribute('data-ind-data');
        if (!body || !dataUrl) return;

        var sidebar = document.querySelector('[data-ind-sidebar]');
        var drawer = document.getElementById('filtersDropup');
        var overlay = document.getElementById('filtersOverlay');
        var drawerBody = document.querySelector('[data-ind-drawer-body]');
        var desktop = window.matchMedia('(min-width: 1024px)');
        var moreSection = document.querySelector('[data-ind-more]');
        var moreGrid = document.querySelector('[data-ind-more-grid]');
        var moreButton = document.querySelector('[data-ind-more-btn]');
        var moreStatus = document.querySelector('[data-ind-more-status]');
        var emptyState = document.querySelector('[data-ind-empty]');
        var activeList = document.querySelector('[data-ind-active-filters]');
        var priceSection = body.querySelector('.price-range-section');
        var sliders = { min: body.querySelector('[data-price-slider="min"]'), max: body.querySelector('[data-price-slider="max"]') };
        var priceInputs = { min: body.querySelector('[data-price-input="min"]'), max: body.querySelector('[data-price-input="max"]') };
        var priceLow = parseFloat(priceSection.getAttribute('data-price-min')) || 0;
        var priceHigh = parseFloat(priceSection.getAttribute('data-price-max')) || 0;
        var searchInput = body.querySelector('[data-ind-search]');
        var checkboxes = Array.prototype.slice.call(body.querySelectorAll('input[data-filter-key]'));
        var keys = [];
        checkboxes.forEach(function (input) {
            var key = input.getAttribute('data-filter-key');
            if (keys.indexOf(key) === -1) keys.push(key);
        });

        var state = { search: [], min: priceLow, max: priceHigh, selected: {} };
        keys.forEach(function (key) { state.selected[key] = []; });

        var data = null;
        var records = [];
        var byCode = {};
        var extras = [];
        var moreList = [];
        var moreShown = 0;
        var lastFocus = null;
        var applyTimer = 0;

        var groups = Array.prototype.slice.call(document.querySelectorAll('[data-ind-group]')).map(function (section) {
            return {
                section: section,
                count: section.querySelector('[data-ind-group-count]'),
                chip: document.querySelector('[data-ind-chip="' + section.id + '"]'),
                cards: Array.prototype.slice.call(section.querySelectorAll('.product-card[data-code]'))
            };
        });

        /* -------- placement: sidebar on desktop, the shop's drawer below 1024px */

        function placeBody() {
            var target = desktop.matches ? sidebar : drawerBody;
            if (target && body.parentNode !== target) target.appendChild(body);
            if (desktop.matches) closeDrawer(false);
        }

        function setOpeners(open) {
            document.querySelectorAll('[data-ind-open-filters]').forEach(function (button) {
                button.setAttribute('aria-expanded', open ? 'true' : 'false');
            });
        }

        function openDrawer() {
            if (!drawer || desktop.matches) return;
            lastFocus = document.activeElement;
            drawer.removeAttribute('inert');
            drawer.classList.add('active');
            if (overlay) overlay.classList.add('active');
            document.body.classList.add('ind-filters-open');
            setOpeners(true);
            var close = drawer.querySelector('.filters-dropup__close');
            if (close) close.focus({ preventScroll: true });
        }

        function closeDrawer(restoreFocus) {
            if (!drawer || !drawer.classList.contains('active')) return;
            drawer.classList.remove('active');
            drawer.setAttribute('inert', '');
            if (overlay) overlay.classList.remove('active');
            document.body.classList.remove('ind-filters-open');
            setOpeners(false);
            if (restoreFocus !== false && lastFocus && lastFocus.focus) lastFocus.focus({ preventScroll: true });
        }

        document.querySelectorAll('[data-ind-open-filters]').forEach(function (button) {
            button.addEventListener('click', openDrawer);
        });
        document.querySelectorAll('[data-ind-close-filters]').forEach(function (button) {
            button.addEventListener('click', function () { closeDrawer(); });
        });
        document.addEventListener('keydown', function (event) {
            if (event.key === 'Escape') closeDrawer();
        });
        if (desktop.addEventListener) desktop.addEventListener('change', placeBody);
        else if (desktop.addListener) desktop.addListener(placeBody);
        placeBody();

        /* -------- expandable sections + "Show more" option lists */

        function toggleRow(row) {
            var expanded = !row.classList.contains('expanded');
            row.classList.toggle('expanded', expanded);
            row.setAttribute('aria-expanded', expanded ? 'true' : 'false');
        }

        body.querySelectorAll('[data-filter-row], .price-range-header').forEach(function (row) {
            var target = row.classList.contains('price-range-header') ? priceSection : row;
            row.addEventListener('click', function (event) {
                if (event.target.closest('button')) return;
                toggleRow(target);
                if (target === priceSection) row.setAttribute('aria-expanded', priceSection.classList.contains('expanded') ? 'true' : 'false');
            });
            row.addEventListener('keydown', function (event) {
                if (event.target !== row || (event.key !== 'Enter' && event.key !== ' ')) return;
                event.preventDefault();
                row.click();
            });
        });

        function refreshList(content) {
            var toggle = content.querySelector('[data-filter-toggle]');
            var search = content.querySelector('[data-filter-search]');
            var query = search ? search.value.trim().toLowerCase() : '';
            var expanded = toggle && toggle.getAttribute('aria-expanded') === 'true';
            var items = content.querySelectorAll('.filter-checkbox-item');
            items.forEach(function (item, index) {
                var input = item.querySelector('input');
                var text = item.textContent.toLowerCase();
                item.classList.toggle('is-hidden-by-search', !!query && text.indexOf(query) === -1);
                item.classList.toggle('is-hidden-by-limit', !query && !expanded && index >= FILTER_VISIBLE_LIMIT && !input.checked);
            });
            if (toggle) {
                toggle.hidden = !!query || items.length <= FILTER_VISIBLE_LIMIT;
                toggle.textContent = expanded ? 'Show less' : 'Show more';
            }
        }

        body.querySelectorAll('.filter-expandable-content').forEach(function (content) {
            var toggle = content.querySelector('[data-filter-toggle]');
            var search = content.querySelector('[data-filter-search]');
            if (toggle) {
                toggle.addEventListener('click', function () {
                    toggle.setAttribute('aria-expanded', toggle.getAttribute('aria-expanded') === 'true' ? 'false' : 'true');
                    refreshList(content);
                });
            }
            if (search) search.addEventListener('input', function () { refreshList(content); });
        });

        /* -------- state changes */

        function scheduleApply(delay) {
            clearTimeout(applyTimer);
            applyTimer = setTimeout(apply, delay || 0);
        }

        checkboxes.forEach(function (input) {
            input.addEventListener('change', function () {
                var key = input.getAttribute('data-filter-key');
                var list = state.selected[key];
                var index = list.indexOf(input.value);
                if (input.checked && index === -1) list.push(input.value);
                if (!input.checked && index > -1) list.splice(index, 1);
                var label = input.closest('[data-filter-option]');
                if (label) label.classList.toggle('is-selected', input.checked);
                apply();
            });
        });

        body.querySelectorAll('[data-filter-clear]').forEach(function (button) {
            button.addEventListener('click', function (event) {
                event.stopPropagation();
                clearKey(button.getAttribute('data-filter-clear'));
                apply();
            });
        });

        searchInput.addEventListener('input', function () {
            state.search = searchInput.value.trim().toLowerCase().split(/\s+/).filter(Boolean);
            scheduleApply(180);
        });

        function money(value) {
            return '\u00A3' + (value * vatFactor()).toFixed(0);
        }

        function renderPrice() {
            var span = priceHigh - priceLow || 1;
            var selected = body.querySelector('[data-price-selected]');
            selected.style.left = ((state.min - priceLow) / span) * 100 + '%';
            selected.style.width = ((state.max - state.min) / span) * 100 + '%';
            sliders.min.value = state.min;
            sliders.max.value = state.max;
            body.querySelector('[data-price-display]').textContent = money(state.min) + ' \u2013 ' + money(state.max) + (vatIsOn() ? ' inc VAT' : ' ex VAT');
            if (document.activeElement !== priceInputs.min) priceInputs.min.value = Math.floor(state.min * vatFactor());
            if (document.activeElement !== priceInputs.max) priceInputs.max.value = Math.ceil(state.max * vatFactor());
        }

        function setPrice(min, max) {
            min = Math.max(priceLow, Math.min(min, priceHigh));
            max = Math.min(priceHigh, Math.max(max, priceLow));
            if (min > max) min = max;
            state.min = min;
            state.max = max;
            renderPrice();
        }

        sliders.min.addEventListener('input', function () {
            setPrice(Math.min(Number(sliders.min.value), state.max), state.max);
            scheduleApply(120);
        });
        sliders.max.addEventListener('input', function () {
            setPrice(state.min, Math.max(Number(sliders.max.value), state.min));
            scheduleApply(120);
        });
        ['min', 'max'].forEach(function (end) {
            priceInputs[end].addEventListener('change', function () {
                var value = parseFloat(priceInputs[end].value);
                if (!isFinite(value)) value = end === 'min' ? priceLow : priceHigh;
                value = end === 'min' ? Math.floor(value / vatFactor()) : Math.ceil(value / vatFactor());
                if (end === 'min') setPrice(value, state.max);
                else setPrice(state.min, value);
                priceInputs.min.value = Math.floor(state.min * vatFactor());
                priceInputs.max.value = Math.ceil(state.max * vatFactor());
                apply();
            });
        });

        function clearKey(key) {
            state.selected[key] = [];
            checkboxes.forEach(function (input) {
                if (input.getAttribute('data-filter-key') !== key) return;
                input.checked = false;
                var label = input.closest('[data-filter-option]');
                if (label) label.classList.remove('is-selected');
            });
        }

        function clearAll() {
            keys.forEach(clearKey);
            searchInput.value = '';
            state.search = [];
            setPrice(priceLow, priceHigh);
            apply();
        }

        document.querySelectorAll('[data-ind-clear]').forEach(function (button) {
            button.addEventListener('click', clearAll);
        });

        /* -------- matching + rendering */

        function matches(record, skip) {
            for (var i = 0; i < state.search.length; i++) {
                if (record.hay.indexOf(state.search[i]) === -1) return false;
            }
            if (skip !== 'price' && (record.p < state.min - 0.001 || record.p > state.max + 0.001)) return false;
            for (var k = 0; k < keys.length; k++) {
                var key = keys[k];
                var wanted = state.selected[key];
                if (key === skip || !wanted.length) continue;
                var values = record.f[key];
                if (!values) return false;
                var hit = false;
                for (var v = 0; v < values.length && !hit; v++) hit = wanted.indexOf(values[v]) > -1;
                if (!hit) return false;
            }
            return true;
        }

        function renderMore(reset) {
            if (!moreGrid) return;
            if (reset) {
                moreGrid.textContent = '';
                moreShown = 0;
            }
            var batch = moreList.slice(moreShown, moreShown + (data.batch || 24));
            if (batch.length) {
                var holder = document.createElement('div');
                holder.innerHTML = batch.map(function (record) { return cardHtml(record, data); }).join('');
                var cards = Array.prototype.slice.call(holder.children);
                cards.forEach(function (card) {
                    moreGrid.appendChild(card);
                    initCard(card);
                    watchDots(card);
                });
                renderPrices(moreGrid);
            }
            moreShown += batch.length;
            var remaining = moreList.length - moreShown;
            moreStatus.textContent = moreList.length ? 'Showing ' + moreShown + ' of ' + styles(moreList.length) : '';
            moreButton.hidden = remaining <= 0;
            moreButton.textContent = 'Show more (' + remaining + ' more)';
        }

        if (moreButton) {
            moreButton.addEventListener('click', function () {
                var first = moreShown;
                renderMore(false);
                var card = moreGrid.children[first];
                var link = card && card.querySelector('.product-name a');
                if (link) link.focus({ preventScroll: true });
            });
        }

        function updateOptions() {
            keys.forEach(function (key) {
                var counts = {};
                records.forEach(function (record) {
                    if (!matches(record, key)) return;
                    (record.f[key] || []).forEach(function (value) { counts[value] = (counts[value] || 0) + 1; });
                });
                var selectedCount = state.selected[key].length;
                checkboxes.forEach(function (input) {
                    if (input.getAttribute('data-filter-key') !== key) return;
                    var label = input.closest('[data-filter-option]');
                    var count = counts[input.value] || 0;
                    var countEl = label.querySelector('.count');
                    if (countEl) countEl.textContent = label.classList.contains('color-swatch-item') ? count : '(' + count + ')';
                    label.classList.toggle('is-zero', count === 0);
                    input.disabled = count === 0 && !input.checked;
                });
                var row = body.querySelector('[data-filter-row="' + key + '"]');
                if (!row) return;
                var badge = row.querySelector('.filter-selection-count');
                badge.hidden = !selectedCount;
                badge.textContent = selectedCount;
                row.querySelector('[data-filter-clear]').hidden = !selectedCount;
                var content = row.nextElementSibling;
                if (content) refreshList(content);
            });
        }

        function updateActive() {
            var pills = [];
            keys.forEach(function (key) {
                state.selected[key].forEach(function (value) {
                    var input = checkboxes.filter(function (box) { return box.getAttribute('data-filter-key') === key && box.value === value; })[0];
                    var row = body.querySelector('[data-filter-row="' + key + '"] h4');
                    var label = input ? input.closest('[data-filter-option]').querySelector('span:not(.count):not(.color-swatch-circle)').textContent : value;
                    pills.push({ text: (row ? row.textContent + ': ' : '') + label, clear: function () { input.checked = false; input.dispatchEvent(new Event('change')); } });
                });
            });
            if (state.min > priceLow || state.max < priceHigh) {
                pills.push({ text: 'Price: ' + money(state.min) + ' \u2013 ' + money(state.max), clear: function () { setPrice(priceLow, priceHigh); apply(); } });
            }
            if (state.search.length) {
                pills.push({ text: 'Search: ' + searchInput.value.trim(), clear: function () { searchInput.value = ''; state.search = []; apply(); } });
            }
            activeList.textContent = '';
            pills.forEach(function (pill) {
                var button = document.createElement('button');
                button.type = 'button';
                button.className = 'ind-active-filter';
                button.setAttribute('aria-label', 'Remove filter ' + pill.text);
                button.innerHTML = escapeHtml(pill.text) + ' <span aria-hidden="true">&times;</span>';
                button.addEventListener('click', pill.clear);
                activeList.appendChild(button);
            });
            if (pills.length > 1) {
                var clear = document.createElement('button');
                clear.type = 'button';
                clear.className = 'ind-active-filter ind-active-filter--clear';
                clear.textContent = 'Clear all';
                clear.addEventListener('click', clearAll);
                activeList.appendChild(clear);
            }
            var badge = document.querySelector('[data-ind-active-count]');
            if (badge) {
                badge.hidden = !pills.length;
                badge.textContent = pills.length;
            }
        }

        function apply() {
            clearTimeout(applyTimer);
            if (!data) return;
            var visible = 0;
            records.forEach(function (record) {
                record.on = matches(record);
                if (record.on) visible++;
            });

            groups.forEach(function (group) {
                var shown = 0;
                group.cards.forEach(function (card) {
                    var record = byCode[card.getAttribute('data-code')];
                    var on = record ? record.on : true;
                    card.hidden = !on;
                    if (on) shown++;
                });
                group.section.hidden = shown === 0;
                group.count.textContent = styles(shown);
                if (group.chip) {
                    group.chip.hidden = shown === 0;
                    group.chip.querySelector('span').textContent = shown;
                }
            });

            if (moreSection) {
                moreList = extras.filter(function (record) { return record.on; });
                moreSection.hidden = moreList.length === 0;
                moreSection.querySelector('[data-ind-group-count]').textContent = styles(moreList.length);
                var chip = document.querySelector('[data-ind-chip="' + moreSection.id + '"]');
                if (chip) {
                    chip.hidden = moreList.length === 0;
                    chip.querySelector('span').textContent = moreList.length;
                }
                renderMore(true);
            }

            document.querySelectorAll('[data-ind-visible-count]').forEach(function (el) { el.textContent = visible; });
            if (emptyState) emptyState.hidden = visible > 0;
            updateOptions();
            updateActive();
            updateJump();
        }

        function setup(json) {
            data = json;
            records = json.products || [];
            records.forEach(function (record) {
                record.hay = (record.c + ' ' + record.n + ' ' + (record.b || '') + ' ' + (record.f.brand || []).join(' ').replace(/-/g, ' ')).toLowerCase();
                if (!byCode[record.c]) byCode[record.c] = record;
            });
            extras = records.filter(function (record) { return record.x; });
            renderPrice();
            apply();
        }

        document.addEventListener('brandeduk:vat-change', renderPrice);
        renderPrice();

        fetch(dataUrl, { credentials: 'same-origin' })
            .then(function (response) {
                if (!response.ok) throw new Error(response.status + ' ' + response.statusText);
                return response.json();
            })
            .then(setup)
            .catch(function (error) {
                console.warn('[industries] Filter data not loaded:', error && error.message);
                if (moreStatus) moreStatus.innerHTML = 'More styles could not be loaded. <a href="/shop-pc.html">Browse the full shop</a>.';
            });
    }

    /* Garments in a basket line: the sum of its sizes, otherwise its own quantity. */
    function basketQty(item) {
        var sizes = item && (item.sizes || item.quantities);
        var values = Array.isArray(sizes) ? sizes
            : sizes && typeof sizes === 'object' ? Object.keys(sizes).map(function (key) { return sizes[key]; }) : [];
        var sum = 0;
        values.forEach(function (entry) {
            sum += Number(entry && typeof entry === 'object' ? (entry.qty || entry.quantity || entry.value) : entry) || 0;
        });
        return sum || Number(item && (item.qty || item.quantity || item.totalQty || item.totalQuantity)) || 0;
    }

    function highlight(text, query) {
        var lower = text.toLowerCase();
        var needle = query.toLowerCase();
        var html = '';
        var from = 0;
        var at = lower.indexOf(needle);
        while (needle && at !== -1) {
            html += escapeHtml(text.slice(from, at)) + '<mark>' + escapeHtml(text.slice(at, at + needle.length)) + '</mark>';
            from = at + needle.length;
            at = lower.indexOf(needle, from);
        }
        return html + escapeHtml(text.slice(from));
    }

    /* Header search: same suggestions and destinations as the mobile home. */
    function initHeaderSearch(input) {
        var wrapper = input.closest('.search-wrapper-expand');
        var icon = wrapper.querySelector('.search-icon-expand');
        var box = document.createElement('div');
        var timer = null;
        box.className = 'search-suggestions';
        wrapper.appendChild(box);

        function shopUrl(query) {
            return '/mobile/shop-mobile.html?q=' + encodeURIComponent(query) + '&force=mobile';
        }

        function render(products, query) {
            if (!products.length) {
                box.classList.remove('active');
                return;
            }
            var on = vatIsOn();
            box.innerHTML = '<div class="suggestion-group-title">Product Results</div>' + products.slice(0, 8).map(function (product) {
                var code = String(product.value || '');
                var label = String(product.label || '').replace(/absolute apparel|ralawise/gi, '').trim();
                var brand = String(product.brand || product.brand_name || '');
                if (/absolute apparel|ralawise/i.test(brand)) brand = '';
                var price = Number(product.price);
                return '<a class="suggestion-item" href="' + productUrl(code) + '">'
                    + '<img class="suggestion-item-image" src="' + escapeHtml(product.image || '/brandedukv15-child/assets/images/ui/no-image.png') + '" alt="" loading="lazy">'
                    + '<div class="suggestion-item-content"><div class="suggestion-item-label">' + highlight(label, query) + '</div>'
                    + '<div class="suggestion-item-sub"><span>Code: ' + escapeHtml(code) + '</span></div></div>'
                    + '<div class="suggestion-item-aside">'
                    + (brand ? '<span class="suggestion-item-brand">' + escapeHtml(brand) + '</span>' : '')
                    + (isFinite(price) && price > 0 ? '<span class="suggestion-item-price">From <strong>\u00A3' + (on ? price * (1 + VAT_RATE) : price).toFixed(2) + '</strong> ' + (on ? 'inc. VAT' : 'ex. VAT') + '</span>' : '')
                    + '</div></a>';
            }).join('') + '<a class="view-all-results" href="' + shopUrl(query) + '">View all results for "' + escapeHtml(query) + '" \u2192</a>';
            box.classList.add('active');
        }

        function suggest(query) {
            if (query.length < 2) {
                box.classList.remove('active');
                return;
            }
            var base = typeof window.resolveBrandedApiBase === 'function' ? window.resolveBrandedApiBase() : 'https://api.brandeduk.com';
            fetch(String(base).replace(/\/+$/, '') + '/api/products/suggest?q=' + encodeURIComponent(query))
                .then(function (response) { return response.ok ? response.json() : null; })
                .then(function (data) {
                    if (query === input.value.trim()) render((data && data.products) || [], query);
                })
                .catch(function () { box.classList.remove('active'); });
        }

        function search() {
            var query = input.value.trim();
            if (query) window.location.href = shopUrl(query);
            else input.focus();
        }

        input.addEventListener('input', function () {
            clearTimeout(timer);
            var query = input.value.trim();
            timer = setTimeout(function () { suggest(query); }, 300);
        });
        input.addEventListener('keydown', function (event) {
            if (event.key === 'Enter') search();
        });
        if (icon) icon.addEventListener('click', search);
        document.addEventListener('click', function (event) {
            if (!wrapper.contains(event.target)) box.classList.remove('active');
        });
    }

    /* Mobile header and menu (same markup as the mobile home). mobile/js/header-menu.js switches the
       menu panels and closes the menu from the toggle; this opens it and runs search, VAT and the basket count. */
    function initMobileHeader() {
        var toggle = document.getElementById('menuToggle');
        var menu = document.getElementById('slideMenu');
        var overlay = document.getElementById('menuOverlay');
        if (!toggle || !menu || !overlay) return;

        function setMenu(open) {
            menu.classList.toggle('active', open);
            overlay.classList.toggle('active', open);
            document.body.style.overflow = open ? 'hidden' : '';
        }
        toggle.addEventListener('click', function () { setMenu(true); });
        overlay.addEventListener('click', function () { setMenu(false); });

        var vatBox = document.getElementById('vatToggleCheckbox');
        var vatWrap = document.getElementById('vatToggleContainer');
        function syncVat() {
            vatBox.checked = vatIsOn();
            vatWrap.classList.toggle('is-on', vatBox.checked);
        }
        vatBox.addEventListener('change', function () {
            var api = window.brandedukv15 && window.brandedukv15.vat;
            if (api) api.set(vatBox.checked);
            syncVat();
        });
        document.addEventListener('brandeduk:vat-change', syncVat);
        syncVat();

        var badge = document.getElementById('cartBadge');
        function syncBadge() {
            var total = 0;
            try {
                JSON.parse(localStorage.getItem('quoteBasket') || '[]').forEach(function (item) { total += basketQty(item); });
            } catch (error) {
                // An unreadable basket shows no count.
            }
            badge.textContent = total > 99 ? '99+' : String(total);
            badge.hidden = total === 0;
        }
        window.addEventListener('storage', syncBadge);
        syncBadge();

        initHeaderSearch(document.getElementById('searchInput'));
    }

    function init() {
        initMobileHeader();

        var cards = Array.prototype.slice.call(document.querySelectorAll('.product-card[data-code]'));
        cards.forEach(function (card) {
            initCard(card);
            watchDots(card);
        });

        renderPrices();
        document.addEventListener('brandeduk:vat-change', function () { renderPrices(); });

        var updateJump = initJump();
        initFilters(updateJump);
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }
})();
